class CorporateActionEventBase(ValidateBaseModel):
    """
    Common envelope fields shared by every variant of [`corporate_action_event`](#/components/schemas/corporate_action_event). This schema is not meant to be used directly by clients -- it exists so each per-`event_type` `oneOf` branch can `allOf`-compose the envelope basics (`event_id`, `at`, `action`, `region`) alongside its narrowed `event_type` / `ca` pair. Keeping these in one place is what makes the envelope's `discriminator` play nicely with strict OpenAPI validators.
    """

    action: CorporateActionEventAction
    at: datetime = Field(
        description="RFC-3339 timestamp when the streaming service emitted this event."
    )
    event_id: Annotated[str, Field(strict=True)] = Field(
        description="Lexically sortable, monotonically increasing 26-character [ULID](https://github.com/ulid/spec) (Crockford Base32, uppercase) that identifies a single SSE emission. Unique per message -- an `update` or `delete` for the same underlying corporate action carries a fresh `event_id`. Because ULIDs sort in emission order, they can be used as resume cursors via `since_id`, `until_id`, or the standard `Last-Event-Id` reconnect header. "
    )
    region: CorporateActionEventRegion


